class Solution {
public:
    int maxA(int n) {
        vector<int> dp(n + 1, 0);
        for (int presses = 1; presses <= n; ++presses) {
            dp[presses] = dp[presses - 1] + 1;
            for (int previous = 1; previous + 3 <= presses; ++previous) {
                int pastes = presses - previous - 2;
                dp[presses] = max(dp[presses], dp[previous] * (pastes + 1));
            }
        }
        return dp[n];
    }
};
